<?php
// Script temporário de instalação do banco — apaga a si mesmo ao final.
@set_time_limit(300);
header('Content-Type: text/plain; charset=utf-8');
require __DIR__.'/../dados/laravel/vendor/autoload.php';
$app = require_once __DIR__.'/../dados/laravel/bootstrap/app.php';
$app->usePublicPath(__DIR__);
$kernel = $app->make(Illuminate\Contracts\Console\Kernel::class);
$kernel->bootstrap();
use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;
try {
    Artisan::call('optimize:clear'); echo Artisan::output();
    Artisan::call('migrate', ['--force' => true]); echo "=== MIGRATE ===\n".Artisan::output();
    $data = json_decode(base64_decode(''), true);
    Schema::disableForeignKeyConstraints();
    foreach ($data as $table => $rows) {
        DB::table($table)->truncate();
        foreach (array_chunk($rows, 50) as $chunk) DB::table($table)->insert($chunk);
        echo "$table: ".DB::table($table)->count()." linhas\n";
    }
    Schema::enableForeignKeyConstraints();
    echo "\nSETUP OK\n";
} catch (\Throwable $e) {
    echo "ERRO: ".get_class($e).": ".$e->getMessage()."\n".$e->getFile().':'.$e->getLine()."\n";
}
@unlink(__FILE__);
